-- 懶貓子
update public.vtubers v set group_id = g.id, activity = 'active', graduated_at = v.graduated_at, debut_date = coalesce(v.debut_date, null), twitch_channel_id = coalesce(v.twitch_channel_id, 'rumi0813'), youtube_channel_id = coalesce(v.youtube_channel_id, 'UCswRX8mNNdn1fjRctZqzjgA') from public.vtuber_groups g where g.name = '預見娛樂' and g.id in (select id from public.vtuber_groups where id = (select id from public.vtuber_groups where name = '預見娛樂' and parent_id is null) or parent_id = (select id from public.vtuber_groups where name = '預見娛樂' and parent_id is null)) and (v.youtube_channel_id = 'UCswRX8mNNdn1fjRctZqzjgA' or lower(v.twitch_channel_id) = 'rumi0813') and (v.group_id is null or v.group_id in (select id from public.vtuber_groups where id = (select id from public.vtuber_groups where name = '預見娛樂' and parent_id is null) or parent_id = (select id from public.vtuber_groups where name = '預見娛樂' and parent_id is null))) and (v.group_id is distinct from g.id or v.activity is distinct from 'active' or v.twitch_channel_id is null or v.youtube_channel_id is null);
